import { ChangeDetectionStrategy, Component } from "@angular/core";
import { CardComponent } from "../../lib/card.component";
import { FancyPillComponent } from "../../lib/fancy-pill.component";
import { PillComponent, type PillVariant } from "../../lib/pill.component";

@Component({
    selector: "app-feature-101",
    changeDetection: ChangeDetectionStrategy.OnPush,
    imports: [ PillComponent, FancyPillComponent, CardComponent ],
    template: `
        <app-card heading="Feature 101" [disableTooltip]="!isActive">
            <p class="hint">This card sets disableTooltip: its title shows no hint.</p>
            <app-pill label="Quiet" variant="info" [disableTooltip]="user?.prefs?.quiet" />
            <app-pill [label]="title" [variant]="statusVariant" [disableTooltip]="items.length === 0" />
            <app-pill label="Keyed" variant="warning" [disableTooltip]="flags['hidden']" />
            <app-pill label="Called" [variant]="count > 2 ? 'success' : 'info'" [disableTooltip]="isHidden() && count > 2" />
            <app-fancy-pill
                [icon]="count > 2 ? 'bolt' : 'star'"
                [disableTooltip]="count > 5"
                label="Fancy" />
        </app-card>
    `
})
export class Feature101Component {
    isActive = false;
    count = 3;
    title = "Title 101";
    statusVariant: PillVariant = "success";
    items: { id: number; name: string; variant: PillVariant; hidden: boolean }[] = [ { id: 1, name: "Alpha", variant: "info", hidden: false }, { id: 2, name: "Beta", variant: "warning", hidden: false } ];
    user?: { prefs?: { quiet: boolean } } = { prefs: { quiet: true } };
    flags: Record<string, boolean> = { hidden: false };

    isHidden(): boolean {
        return this.count > 4;
    }
}
<app-card heading="Feature 104" [disableTooltip]="true">
  <app-pill disableTooltip label='Plain'/>
  <app-pill  variant="success"  [disableTooltip]='!isActive'  label="Active"/>
  <app-pill [disableTooltip]="count > 3" [label]="title" variant="info" />
  <app-pill [variant]="isActive ? 'success' : 'warning'" label="Multi-line" disableTooltip></app-pill>
  @if (isActive) {
    <app-pill-legacy label="Legacy" variant="info" [disableTooltip]="true" />
  }
  <app-fancy-pill
    #fancyRef
    [icon]="count > 2 ? 'bolt' : 'star'"
    [disableTooltip]="count > 5"
    label="Fancy" />
  <small>Fancy hint: {{ fancyRef.disableTooltip() ? 'off' : 'on' }}</small>
  <app-status-pill disableTooltip label="Status" variant="success"></app-status-pill>
</app-card>
<app-card heading="Screen flag" [disableTooltip]="disableTooltip" />
<app-card
    heading="Feature 105"
    [disableTooltip]="true"
>
    <!-- disableTooltip above is the card's flag: no hint on the title -->
    <app-pill
        label="Plain"
        variant="warning"
        disableTooltip
    />
    <app-pill
        [label]="title"
        [variant]="count > 3 ? 'success' : isActive ? 'warning' : 'info'"
        [disableTooltip]="!(isActive && count > 1)"
    />
    <app-pill [variant]="statusVariant" label="Nested" [disableTooltip]="false" />
</app-card>
<app-card heading="Summary" [disableTooltip]="!isActive" />
